(()=>{
const answer='待结转余量/余额为负，明显超出核算基线的数据波动、不符合业务场景假设的数据波动';
const analysis='异常分析：通过数据分析追溯，明确异常根因，如：\n① 财经作业异常（如：手工调整错误，导致余额为负数；合同已结清但是历史手工调整未执行）\n② 供应作业异常（如：退货操作异常，撤货BOQ选错）\n③ 交付作业异常（如：完成交付后，未获取支撑开票文档）\n④ 多维度发散（BI报告多维度数据缺失，导致数据异常）';
const defaultRule='按照地区部、代表处、国家、项目、合同、DU、PL、货龄、金额进行数据加工，超期站点存货、超期借货、超期在途、超期未核销RMA数据';
const rulePrefix='超期&异常存货识别规则一般为“';
const dimensionPrefix='异常分析一般分为四个维度：\n';
const scheduleSuffix='会自动查询您权限下的超期&异常存货情况。';
function isScheduleMessage(text){return String(text).endsWith(scheduleSuffix)||(String(text).startsWith('是否生成自动任务“')&&String(text).endsWith('”'))}
function scheduleText(time){const [h,m]=time.split(':').map(Number);const sentence='每天'+(h<12?'上午':'下午')+(h%12||12)+'点'+(m?String(m):'')+scheduleSuffix;return '是否生成自动任务“'+sentence.slice(0,-1)+'”'}
function renderSchedule(body,text){
 body.classList.add('inventory-risk-schedule');body.setAttribute('role','group');body.setAttribute('aria-label','每日自动查询安排');const scope=currentSessionId;let time='08:30',editing=false,confirmed=false;
 const record=()=>{const list=sessionRecords.find(x=>x.id===scope)?.messages||[];for(let i=list.length-1;i>=0;i--)if(list[i].text===text)return list[i]};
 const initial=record();time=initial?.scheduleTime||time;confirmed=Boolean(initial?.scheduleConfirmed);
 const intro=document.createElement('p');intro.className='risk-rule-text';intro.textContent=scheduleText(time);
 const editor=document.createElement('div');editor.className='risk-schedule-editor';editor.hidden=true;const label=document.createElement('label');label.textContent='每日查询时间';const input=document.createElement('input');input.type='time';input.value=time;input.required=true;input.setAttribute('aria-label','自动查询时间');label.append(input);const tz=document.createElement('small');tz.textContent='北京时间（UTC+8）';editor.append(label,tz);
 const actions=document.createElement('div');actions.className='risk-rule-actions';actions.innerHTML='<button type="button" class="risk-rule-confirm">确认</button><button type="button" class="risk-rule-edit">修改</button>';const confirm=actions.firstElementChild,edit=actions.lastElementChild;confirm.disabled=confirmed;
 const status=document.createElement('div');status.className='risk-rule-status';status.setAttribute('role','status');if(confirmed)status.textContent='✓ 自动查询安排已确认 · 每天 '+time+'（北京时间）';
 edit.onclick=()=>{if(currentSessionId!==scope)return;editing=!editing;editor.hidden=!editing;intro.hidden=editing;edit.textContent=editing?'取消修改':'修改';confirm.disabled=editing?false:confirmed;if(editing){input.value=time;input.focus()}};
 confirm.onclick=()=>{if(busy||currentSessionId!==scope)return;const next=editing?input.value:time;if(!next){input.reportValidity();return}time=next;const item=record(),nextText=scheduleText(time);if(item){item.text=nextText;item.scheduleTime=time;item.scheduleConfirmed=true;saveSessionRecords()}text=nextText;confirmed=true;editing=false;intro.textContent=nextText;intro.hidden=false;editor.hidden=true;edit.textContent='修改';confirm.disabled=true;
 const key='herp-inventory-accountant-automation-v1';let jobs=[];try{jobs=JSON.parse(localStorage.getItem(key))||[]}catch(e){}if(!Array.isArray(jobs))jobs=[];const job={id:'inventory-risk-daily',name:'每日超期&异常存货识别',type:'scheduled',agent:'存货核算会计助手',skill:'超期&异常存货识别',trigger:'每天 '+time,time,frequency:'daily',timezone:'Asia/Shanghai',scope:'当前用户权限范围',policy:'仅查询和识别，业务变更需确认',prompt:'超期&异常存货识别',paused:false,lastRun:'尚未执行',role:'inventory-accountant'};const at=jobs.findIndex(x=>x.id===job.id);if(at>=0)jobs[at]={...jobs[at],...job};else jobs.unshift(job);localStorage.setItem(key,JSON.stringify(jobs));document.getElementById('automation-view')?.remove();status.textContent='✓ 自动查询安排已确认 · 每天 '+time+'（北京时间）';
 };
 body.append(intro,editor,actions,status);
}

const defaultDimensions=[
'① 财经作业异常（如：手工调整错误，导致余额为负数；合同已结清但是历史手工调整未执行）',
'② 供应作业异常（如：退货操作异常，撤货BOQ选错）',
'③ 交付作业异常（如：完成交付后，未获取支撑开票文档）',
'④ 多维度发散（BI报告多维度数据缺失，导致数据异常）'];
function renderDimensions(body,text){
 body.classList.add('inventory-risk-analysis','inventory-risk-dimensions');body.setAttribute('role','group');body.setAttribute('aria-label','异常分析维度确认');
 const scope=currentSessionId;let lines=text===analysis?defaultDimensions.slice():text.slice(dimensionPrefix.length).split('\n').filter(x=>x.trim()),editing=false;
 const content=document.createElement('div');content.className='risk-dimension-content';
 function draw(){content.replaceChildren();const title=document.createElement('p');const b=document.createElement('b');b.textContent=lines.length===4?'异常分析一般分为四个维度：':'异常分析维度（'+lines.length+'个）：';title.append(b);content.append(title);lines.forEach(line=>{const p=document.createElement('p'),at=line.indexOf('（');const strong=document.createElement('strong'),em=document.createElement('em');em.textContent=at<0?line:line.slice(0,at);strong.append(em);p.append(strong);if(at>=0)p.append(document.createTextNode(line.slice(at)));content.append(p)})}draw();
 const question=document.createElement('p');question.className='risk-dimension-question';question.textContent='是否需要增加新的维度？';
 const editor=document.createElement('textarea');editor.className='risk-rule-editor risk-dimension-editor';editor.setAttribute('aria-label','修改异常分析维度');editor.value=lines.join('\n');editor.placeholder='每行一个分析维度，可编辑现有维度或在末尾增加新维度';editor.hidden=true;
 const actions=document.createElement('div');actions.className='risk-rule-actions';actions.innerHTML='<button type="button" class="risk-rule-confirm">确认</button><button type="button" class="risk-rule-edit">修改</button>';const confirm=actions.firstElementChild,edit=actions.lastElementChild;
 const status=document.createElement('div');status.className='risk-rule-status';status.setAttribute('role','status');
 const entry=()=>sessionRecords.find(x=>x.id===scope);const record=()=>{const list=entry()?.messages||[];for(let i=list.length-1;i>=0;i--)if(list[i].text===text)return list[i]};
 const complete=record()?.dimensionsConfirmed||(text===analysis&&entry()?.messages.some(m=>m.text===answer));if(complete){confirm.disabled=true;edit.disabled=true;status.textContent='✓ 分析维度已确认'}
 edit.onclick=()=>{if(currentSessionId!==scope)return;editing=!editing;editor.hidden=!editing;content.hidden=editing;edit.textContent=editing?'取消修改':'修改';if(editing){editor.value=lines.join('\n');editor.focus()}};
 editor.oninput=()=>editor.setCustomValidity('');
 confirm.onclick=()=>{if(busy||currentSessionId!==scope)return;const next=editing?editor.value.split('\n').map(x=>x.trim()).filter(Boolean):lines;if(!next.length){editor.setCustomValidity('请至少保留一个分析维度');editor.reportValidity();return}const item=record();lines=next;const nextText=dimensionPrefix+lines.join('\n');if(item){item.text=nextText;item.dimensionsConfirmed=true;saveSessionRecords()}text=nextText;draw();content.hidden=false;editor.hidden=true;confirm.disabled=true;edit.disabled=true;edit.textContent='修改';status.textContent='✓ 分析维度已确认';addMessage('确认以上分析维度，继续识别。',true);runResults()};
 body.append(content,editor,question,actions,status);
}

function renderRules(body,text){
 body.classList.add('inventory-risk-rules');body.setAttribute('role','group');body.setAttribute('aria-label','存货识别规则确认');const scope=currentSessionId;let rule=text.slice(rulePrefix.length,-1),editing=false;
 const intro=document.createElement('p');intro.className='risk-rule-text';intro.textContent=rulePrefix+rule+'”';
 const editor=document.createElement('textarea');editor.className='risk-rule-editor';editor.setAttribute('aria-label','修改存货识别规则');editor.value=rule;editor.hidden=true;
 const actions=document.createElement('div');actions.className='risk-rule-actions';actions.innerHTML='<button type="button" class="risk-rule-confirm">确认</button><button type="button" class="risk-rule-edit">修改</button>';const confirm=actions.firstElementChild,edit=actions.lastElementChild;
 const status=document.createElement('div');status.className='risk-rule-status';status.setAttribute('role','status');
 const record=()=>{const list=sessionRecords.find(x=>x.id===scope)?.messages||[];for(let i=list.length-1;i>=0;i--)if(list[i].text===text)return list[i]};
 const saved=record();if(saved?.ruleConfirmed){confirm.disabled=true;edit.disabled=true;status.textContent='✓ 识别规则已确认'}
 edit.onclick=()=>{if(currentSessionId!==scope)return;editing=!editing;editor.hidden=!editing;intro.hidden=editing;edit.textContent=editing?'取消修改':'修改';if(editing){editor.value=rule;editor.focus()}};
 editor.oninput=()=>editor.setCustomValidity('');
 confirm.onclick=()=>{if(busy||currentSessionId!==scope)return;const next=editing?editor.value.trim():rule;if(!next){editor.setCustomValidity('请输入识别规则');editor.reportValidity();return}const item=record();rule=next;const nextText=rulePrefix+rule+'”';if(item){item.text=nextText;item.ruleConfirmed=true;saveSessionRecords()}text=nextText;intro.textContent=nextText;intro.hidden=false;editor.hidden=true;confirm.disabled=true;edit.disabled=true;edit.textContent='修改';status.textContent='✓ 识别规则已确认';addMessage('确认识别规则，继续分析。',true);runDimensions()};
 body.append(intro,editor,actions,status);
}
const baseMessage=addMessage;addMessage=function(text,user){const result=baseMessage.apply(this,arguments);if(!user&&(text===answer||text===analysis||isScheduleMessage(text)||String(text).startsWith(dimensionPrefix)||String(text).startsWith(rulePrefix))){const message=document.getElementById('messages').lastElementChild;if(message){const author=message.querySelector(':scope > strong');if(author)author.textContent='存货核算会计助手';const body=document.createElement('div');body.className='inventory-risk-message';if(text===answer||isScheduleMessage(text)){renderSchedule(body,text)}else if(text===analysis||String(text).startsWith(dimensionPrefix)){renderDimensions(body,text)}else{renderRules(body,text)}message.replaceChildren(...(author?[author]:[]),body);if(text===answer)message.dataset.riskStage='result';if(text===analysis){const prior=document.getElementById('messages').querySelector('[data-risk-stage="result"]');if(prior)prior.before(message)}}}return result};
let busy=false,generation=0,timers=[],thinking=null;
function stopPending(){generation++;timers.forEach(clearTimeout);timers=[];thinking?.remove();thinking=null;busy=false;document.getElementById('messages').removeAttribute('aria-busy');refreshSend()}
function showThinking(label){thinking?.remove();thinking=document.createElement('div');thinking.className='chatmessage inventory-risk-thinking';thinking.setAttribute('role','status');thinking.setAttribute('aria-live','polite');thinking.innerHTML='<strong>存货核算会计助手</strong><div class="inventory-risk-message"><span class="risk-thinking-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>'+label+'</span></div>';document.getElementById('messages').append(thinking);const log=document.getElementById('chatlog');log.scrollTop=log.scrollHeight}
const baseRefresh=refreshSend;refreshSend=function(...args){const result=baseRefresh.apply(this,args);if(busy)document.getElementById('sendBtn').disabled=true;return result};
function finishPending(){busy=false;timers=[];document.getElementById('messages').removeAttribute('aria-busy');refreshSend()}
function runDimensions(){stopPending();busy=true;refreshSend();const token=++generation;document.getElementById('messages').setAttribute('aria-busy','true');showThinking('正在梳理异常分析维度…');timers.push(setTimeout(()=>{if(token!==generation)return;thinking?.remove();thinking=null;addMessage(dimensionPrefix+defaultDimensions.join('\n'),false);document.getElementById('prompt').placeholder='请确认分析维度，或点击“修改”补充新的维度…';finishPending()},1100))}
function runResults(){stopPending();busy=true;refreshSend();const token=++generation;document.getElementById('messages').setAttribute('aria-busy','true');showThinking('正在生成每日自动查询安排…');timers.push(setTimeout(()=>{if(token!==generation)return;thinking?.remove();thinking=null;addMessage(scheduleText('08:30'),false);document.getElementById('prompt').placeholder='请确认自动查询安排，或点击“修改”调整时间…';finishPending()},1100))}
const baseSend=sendPrompt;sendPrompt=function(){if(busy)return;const q=document.getElementById('prompt').value.trim();if(sessionStorage.getItem('yunxu-role')==='inventory-accountant'&&/超期站点存货|超期.*异常存货识别/.test(q)){stopPending();addMessage(q,true);document.getElementById('prompt').value='';busy=true;refreshSend();const token=++generation;document.getElementById('messages').setAttribute('aria-busy','true');showThinking('正在分析超期与异常存货识别规则…');timers.push(setTimeout(()=>{if(token!==generation)return;thinking?.remove();thinking=null;addMessage(rulePrefix+defaultRule+'”',false);document.getElementById('prompt').placeholder='请确认识别规则，或点击“修改”调整规则…';finishPending()},1100));return}return baseSend.apply(this,arguments)};
for(const key of ['openNewConversation','setModule','openActivityBoard','openSkillMarket','openAutomationTasks','openMySpace','showRoleSelection','enterWorkspace']){const original=window[key];if(typeof original==='function')window[key]=function(...args){stopPending();return original.apply(this,args)}}
const style=document.createElement('style');style.textContent='body[data-system-theme] #messages .inventory-risk-message{line-height:1.9;font-size:14px;color:#111827;background:#fff;border:1px solid #e0e6ef;border-radius:12px;padding:16px 18px;box-shadow:0 2px 7px #253b5205}body[data-system-theme] #messages .inventory-risk-message strong,body[data-system-theme] #messages .inventory-risk-message em{color:#D92D20!important;font-weight:700!important;font-style:italic!important}body[data-system-theme] #messages .inventory-risk-message strong,body[data-system-theme] #messages .inventory-risk-message em{display:inline!important;font-size:14px!important;line-height:inherit!important;opacity:1!important;margin:0!important}.inventory-risk-analysis p{margin:0 0 14px}.inventory-risk-analysis p:last-child{margin-bottom:0}.inventory-risk-thinking .inventory-risk-message{display:flex;align-items:center;gap:12px;color:#667085!important}.risk-thinking-dots{display:inline-flex;align-items:center;gap:4px}.risk-thinking-dots i{display:block;width:5px;height:5px;border-radius:50%;background:#0067D1;animation:risk-thinking-pulse 1s ease-in-out infinite}.risk-thinking-dots i:nth-child(2){animation-delay:.15s}.risk-thinking-dots i:nth-child(3){animation-delay:.3s}@keyframes risk-thinking-pulse{0%,80%,100%{opacity:.3;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}@media(prefers-reduced-motion:reduce){.risk-thinking-dots i{animation:none;opacity:.7}}.inventory-risk-rules .risk-rule-text{margin:0;line-height:1.9}.risk-rule-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.risk-rule-actions button{font:inherit;font-size:14px;padding:8px 20px;border:1px solid #dce3ed;border-radius:7px;background:white;color:#344054;cursor:pointer}.risk-rule-actions button.risk-rule-confirm{background:#0067D1;border-color:#0067D1;color:#fff}.risk-rule-actions button:disabled{opacity:.5;cursor:default}.risk-rule-editor{display:block;width:100%;box-sizing:border-box;min-height:120px;padding:10px 12px;resize:vertical;font:inherit;line-height:1.8;color:#111827;border:1px solid #b9d5f2;border-radius:8px;background:#fbfdff}.risk-rule-editor[hidden],.risk-rule-text[hidden]{display:none!important}.risk-rule-status{margin-top:10px;font-size:12px;color:#178258}.risk-rule-status:empty{display:none}.risk-dimension-content[hidden]{display:none!important}.risk-dimension-question{margin:18px 0 0!important;color:#344054}.risk-dimension-editor{min-height:210px!important}body[data-system-theme] #messages .inventory-risk-message.inventory-risk-dimensions strong,body[data-system-theme] #messages .inventory-risk-message.inventory-risk-dimensions em{color:#000!important;font-style:normal!important;font-weight:700!important}.risk-schedule-editor{display:flex;align-items:flex-end;gap:14px;padding:12px 0}.risk-schedule-editor[hidden]{display:none!important}.risk-schedule-editor label{display:grid;gap:8px;font-size:14px;color:#344054}.risk-schedule-editor input{font:inherit;border:1px solid #cbdced;border-radius:7px;padding:8px 12px;background:#fff;color:#111827}.risk-schedule-editor small{color:#7b8797;font-size:12px;padding-bottom:8px}';document.head.append(style);
})();
